import pandas as pd

def clean(df):
    df = df.copy()

    for col in ["species", "island", "sex"]:
        if col in df.columns:
            df[col] = df[col].astype("string").str.strip()

    if "species" in df.columns:
        df["species"] = df["species"].replace({"Gentto": "Gentoo", "Adeile": "Adelie"})

    if "island" in df.columns:
        df["island"] = df["island"].replace({"biscoe": "Biscoe"})

    if "sex" in df.columns:
        df["sex"] = df["sex"].str.lower()
        df.loc[~df["sex"].isin(["male", "female"]), "sex"] = pd.NA

    if "body_mass_g" in df.columns:
        bm = df["body_mass_g"].astype("string").str.replace(",", "", regex=False).str.strip()
        bm = pd.to_numeric(bm, errors="coerce")
        mask = bm > 6500
        fixable = mask & (bm / 1000).between(2500, 6500)
        bm.loc[fixable] = bm.loc[fixable] / 1000
        bm.loc[~bm.between(2500, 6500)] = pd.NA
        df["body_mass_g"] = bm

    for col in ["bill_length_mm", "bill_depth_mm", "flipper_length_mm", "year"]:
        if col in df.columns:
            df[col] = pd.to_numeric(
                df[col].astype("string").str.replace(",", "", regex=False),
                errors="coerce"
            )

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=["sex", "body_mass_g"])
    result = d.groupby("sex")["body_mass_g"].mean()
    return {str(k): float(v) for k, v in result.items()}
